<div class="pagination-bar"><span>Menampilkan <strong><?= $paginationPage['total'] ? (($paginationPage['page']-1)*$paginationPage['per_page']+1).'–'.min($paginationPage['page']*$paginationPage['per_page'],$paginationPage['total']) : '0' ?></strong> dari <strong><?= number_format($paginationPage['total'],0,',','.') ?></strong> transaksi</span><nav class="pagination" aria-label="Navigasi halaman"><?php $urlForPage=static function(int $n) use($paginationParams):string{$v=$paginationParams;$v['p']=$n;return '?'.http_build_query($v);}; ?><a class="page-link <?= $paginationPage['page']<=1?'disabled':'' ?>" href="<?= e($urlForPage(max(1,$paginationPage['page']-1))) ?>">‹</a><?php $start=max(1,$paginationPage['page']-2);$end=min($paginationPage['pages'],$paginationPage['page']+2);for($n=$start;$n<=$end;$n++): ?><a class="page-link <?= $n===$paginationPage['page']?'active':'' ?>" href="<?= e($urlForPage($n)) ?>"><?= $n ?></a><?php endfor; ?><a class="page-link <?= $paginationPage['page']>=$paginationPage['pages']?'disabled':'' ?>" href="<?= e($urlForPage(min($paginationPage['pages'],$paginationPage['page']+1))) ?>">›</a></nav></div>
